const conocimiento = FRAGMENTOS
  .map((f) => '### ' + f.titulo + ' (novuchat.site' + f.url + ')\n' + f.texto)
  .join('\n\n');

return $input.all().map((it, i) => ({ json: { ...it.json,
  conocimiento, conocimientoHuella: HUELLA, conocimientoGenerado: GENERADO,
}, pairedItem: { item: i } }));

// Normaliza el payload de la Cloud API (regla "normalizacion de entrada" de
// CLAUDE.md) y arrastra lo que puso `Config del negocio`. Nunca se accede a
// `.text.body` fuera de este nodo.
//
// LO PROPIO DE ESTE FLUJO:
//  - `eleccion`: lo que el cliente eligio en los botones de bienvenida
//    (`cliente_actual` / `cliente_nuevo`). Tambien se reconoce ESCRITO: quien
//    contesta «ya soy cliente» en vez de tocar el boton no tiene que tocarlo.
//  - `anuncio`: si el mensaje viene de un anuncio de clic a WhatsApp, Meta manda
//    `referral`. Sirve para que el asistente sepa por que escribe la persona, y
//    para medir la ventana de punto de entrada gratuito (CLAUDE.md §6).
//  - Una imagen o un documento NO se asumen como comprobante: este flujo no
//    cobra. Se pide que lo escriba.
const CLIENTE_ACTUAL = /\b(ya\s+soy\s+cliente|soy\s+cliente(\s+de\s+novuchat)?|ya\s+tengo\s+(novuchat|el\s+asistente|la\s+consola)|mi\s+consola|entrar\s+a\s+(la\s+|mi\s+)?consola|mi\s+cuenta\s+de\s+novuchat)\b/i;
const SALUDO = /^(hola|ola|buen(a|o)s?( d[ií]as| tardes| noches)?|hey|holi|qu[eé] tal|saludos)[\s!¡.,?¿👋🙂😊]*$/i;

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const src = items[i].json;

  // Config viene mezclada con el payload de Meta: se separa sin listar campo
  // por campo. `conocimiento` se descarta: son 16 mil caracteres que el agente
  // lee directo de su nodo, y no tienen por que viajar en cada item.
  const cfg = { ...src };
  for (const k of ['messages', 'contacts', 'statuses', 'errors', 'metadata',
                   'messaging_product', 'conocimiento']) {
    delete cfg[k];
  }

  const msg = Array.isArray(src.messages) ? src.messages[0] : undefined;
  if (!msg) continue; // acuse de estado u otro evento: no deberia llegar aca

  const tipo = msg.type ?? 'desconocido';
  let userInput = '';
  let esSaludo = false;
  let eleccion = '';

  switch (tipo) {
    case 'text': {
      userInput = msg.text?.body ?? '';
      esSaludo = SALUDO.test(userInput.trim());
      if (CLIENTE_ACTUAL.test(userInput)) eleccion = 'cliente_actual';
      break;
    }
    case 'interactive': {
      const r = msg.interactive?.button_reply ?? msg.interactive?.list_reply;
      const id = String(r?.id ?? '');
      if (id === 'cliente_actual' || id === 'cliente_nuevo') eleccion = id;
      userInput = id === 'cliente_nuevo' ? 'Quiero conocer NovuChat.'
        : id === 'cliente_actual' ? 'Ya soy cliente de NovuChat.'
        : 'El cliente toco: ' + (r?.title ?? '') + '. Tomalo como si te lo hubiera escrito.';
      break;
    }
    case 'button': {
      userInput = 'El cliente pulso el boton: ' + (msg.button?.text ?? '');
      break;
    }
    case 'image':
    case 'document':
    case 'video': {
      const cap = msg[tipo]?.caption ? ' Escribio junto al archivo: "' + msg[tipo].caption + '".' : '';
      userInput = 'AVISO_SISTEMA: el cliente envio un archivo (' + tipo + ') que no puedes ver.' + cap +
        ' Pidele con amabilidad que te escriba en texto lo que necesita.';
      break;
    }
    case 'audio':
    case 'voice': {
      userInput = 'AVISO_SISTEMA: el cliente envio una NOTA DE VOZ que no puedes escuchar. ' +
        'Pidele con amabilidad que te lo escriba.';
      break;
    }
    case 'location': {
      const loc = msg.location ?? {};
      userInput = 'AVISO_SISTEMA: el cliente compartio una ubicacion' +
        (loc.address ? ' (' + loc.address + ')' : '') +
        '. Si es la de su negocio, agradecela y sigue la conversacion.';
      break;
    }
    case 'sticker':
    case 'contacts':
    default: {
      userInput = 'AVISO_SISTEMA: el cliente envio un mensaje de tipo "' + tipo +
        '" que no puedes leer. Respondele con cortesia que por ahora atiendes por texto.';
    }
  }

  const ref = msg.referral;
  const anuncio = ref ? {
    titular: String(ref.headline ?? '').slice(0, 120),
    fuente: String(ref.source_type ?? ''),
    url: String(ref.source_url ?? '').slice(0, 200),
  } : null;

  const contacto = Array.isArray(src.contacts) ? src.contacts[0] : undefined;

  out.push({ json: Object.assign({}, cfg, {
    userInput,
    tipo,
    esSaludo,
    eleccion,
    anuncio,
    from: msg.from,
    mensajeId: msg.id ?? '',
    nombrePerfil: contacto?.profile?.name ?? '',
  }), pairedItem: { item: i } });
}
return out;

// El comercio no esta operativo (suspendido o dado de baja). Aplica tambien a
// NovuChat: si alguien suspende el tenant `novuchat`, este flujo deja de
// atender, igual que el de cualquier cliente. Se corta ANTES del agente, asi
// que no consume tokens.
//
// PROHIBIDO REVELAR EL MOTIVO: el texto es neutro y sale de la configuracion.
const cfg = $('Config del negocio').first().json;
const aviso = String(cfg.mensajeComercioSuspendido ?? '').trim()
  || 'En este momento no podemos atenderte por este medio. Gracias por escribirnos.';

return $input.all().map((it, i) => ({ json: { ...it.json,
  respuesta: aviso,
  comercioSuspendido: true,
}, pairedItem: { item: i } }));

// ESTADO DE LA CONVERSACION: decide que hace este turno, ANTES de llamar al
// modelo. Es donde viven la compuerta inicial, el fin del primer bloque y la
// idempotencia.
//
// EL TECHO DE COSTO LO DECIDE EL SERVIDOR, no este nodo. `Config del negocio`
// trae `atencionEstado` -- normal, operador o bloqueado --, calculado con los
// umbrales de la cuenta del tenant (`atencion.ts`), igual que en los flujos A
// y B. Aca solo se obedece: en operador o bloqueado el agente no se alcanza.
//
// LO QUE SI SE GUARDA ACA, en los datos estaticos del flujo, por telefono: la
// etapa (bienvenida, cliente actual, cliente nuevo, cerrado), los datos del
// prospecto y los ids de mensaje ya procesados. No es informacion que el
// servidor tenga, y no se factura sobre ella. n8n guarda los datos estaticos
// solo en ejecuciones de PRODUCCION (el disparador publicado); probando desde
// el editor, cada ejecucion arranca de cero.
//
// QUE DECIDE (campo `accion`):
//   uso_extendido   el servidor dice operador o bloqueado: mensaje fijo o
//                   silencio, y aviso a una persona. Sin modelo.
//   bienvenida      primer «hola» suelto: los dos botones, sin modelo. Queda
//                   marcada solo si Meta acepta el envio (`Confirmar envio`).
//   cliente_actual  eligio «Soy cliente actual» (o lo escribio): un mensaje
//                   con la consola y un boton a una persona, sin modelo.
//   agente          todo lo demas.
// Y NO DEVUELVE NADA -- el flujo termina sin responder -- en dos casos:
//   - el mismo `mensajeId` ya se proceso: Meta reenvia el evento si n8n tarda,
//     y sin esto el prospecto recibe dos respuestas (Analisis/25 §3.3);
//   - el telefono esta bloqueado y ya se aviso: no hay nada que enviar.
const VENTANA_MS = 24 * 60 * 60 * 1000;
const DEDUP_MS = 10 * 60 * 1000;
const OLVIDO_MS = 48 * 60 * 60 * 1000;
const CAMPOS = ['empresa', 'contacto', 'rubro', 'flujos', 'personalizacion', 'nit'];

const sd = $getWorkflowStaticData('global');
sd.vistos = sd.vistos ?? {};
sd.conversaciones = sd.conversaciones ?? {};
const ahora = Date.now();

// Limpieza: los ids se recuerdan 10 minutos; las conversaciones, 48 horas sin
// mensajes. Sin esto los datos estaticos crecen para siempre.
for (const [id, t] of Object.entries(sd.vistos)) {
  if (ahora - t > DEDUP_MS) delete sd.vistos[id];
}
for (const [tel, c] of Object.entries(sd.conversaciones)) {
  if (ahora - (c.ultimo ?? 0) > OLVIDO_MS) delete sd.conversaciones[tel];
}

const hora = new Date(ahora).toLocaleString('es-BO', {
  timeZone: 'America/La_Paz', weekday: 'long', day: 'numeric', month: 'long',
  year: 'numeric', hour: '2-digit', minute: '2-digit',
});

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const e = items[i].json;

  if (e.mensajeId && sd.vistos[e.mensajeId]) continue;   // reenvio de Meta
  if (e.mensajeId) sd.vistos[e.mensajeId] = ahora;

  const nueva = !sd.conversaciones[e.from];
  const c = sd.conversaciones[e.from] ?? {
    desde: ahora, respuestas: 0, etapa: '', bienvenida: false, avisado: false, lead: {},
  };
  // Contador PROPIO solo como respaldo del fin del primer bloque, para cuando el
  // panel no contesta. Ventana fija de 24 horas, como la del servidor.
  if (ahora - c.desde >= VENTANA_MS) { c.desde = ahora; c.respuestas = 0; }
  c.ultimo = ahora;

  const estadoServidor = e.atencionEstado === 'operador' || e.atencionEstado === 'bloqueado'
    ? e.atencionEstado : 'normal';

  let accion;
  if (estadoServidor !== 'normal') {
    accion = 'uso_extendido';
  } else if (e.eleccion === 'cliente_actual' && c.etapa !== 'cliente_actual') {
    accion = 'cliente_actual'; c.etapa = 'cliente_actual';
  } else if (e.eleccion === 'cliente_nuevo') {
    accion = 'agente'; if (c.etapa !== 'cerrado') c.etapa = 'cliente_nuevo';
  } else if (!c.etapa && e.esSaludo && !c.bienvenida) {
    // Un «hola» suelto: los botones. Una sola vez; si vuelve a saludar sin
    // elegir, sigue el asistente y no se le repiten los botones.
    // `c.bienvenida` NO se marca aca: la marca `Confirmar envio` cuando Meta
    // acepto el mensaje. Marcada antes de enviar, un envio fallido dejaba a
    // ese telefono sin botones para siempre (aceptacion del 15/09/2026).
    accion = 'bienvenida';
  } else {
    // Quien ya dijo lo que quiere -- «hola, cuanto cuesta» -- no tiene que
    // tocar ningun boton: pasa directo al asistente como cliente nuevo.
    accion = 'agente'; if (!c.etapa) c.etapa = 'cliente_nuevo';
  }

  // Bloqueado y ya avisado: no hay mensaje ni aviso que mandar.
  const avisaServidor = e.atencionAvisarRecepcion === 'operador' || e.atencionAvisarRecepcion === 'bloqueado';
  if (estadoServidor === 'bloqueado' && !avisaServidor) { sd.conversaciones[e.from] = c; continue; }

  // La respuesta que se va a enviar es la numero `siguiente` de la ventana. Se
  // toma el conteo del SERVIDOR cuando llego; el propio es el respaldo.
  const enviadas = typeof e.atencionRespuestas === 'number' ? e.atencionRespuestas : c.respuestas;
  const siguiente = enviadas + 1;
  if (estadoServidor !== 'bloqueado') c.respuestas = siguiente;
  sd.conversaciones[e.from] = c;

  const topeAviso = Number(e.topeAviso) || 25;
  const finBloque = accion === 'agente' && siguiente === topeAviso;
  const lead = c.lead ?? {};
  const faltan = CAMPOS.filter((k) => !lead[k]);
  const modo = c.etapa === 'cliente_actual' ? 'CLIENTE ACTUAL' : 'CLIENTE NUEVO';

  // EL MENSAJE DEL TURNO lleva todo lo que cambia entre un turno y otro -- la
  // hora, quien escribe, los datos ya registrados, el contador -- para que las
  // instrucciones del agente queden fijas y el proveedor pueda cachearlas.
  const mensajeDelTurno = [
    '[CONTEXTO DEL TURNO - no lo repitas al cliente]',
    'Fecha y hora en La Paz: ' + hora + '.',
    'Modo: ' + modo + '.',
    'Nombre de perfil de WhatsApp: ' + (e.nombrePerfil || 'sin nombre') + '.',
    'Datos ya registrados: ' + JSON.stringify(lead) + '. Faltan: ' + (faltan.join(', ') || 'ninguno') + '.',
    c.etapa === 'cerrado' ? 'Ya se aviso a un asesor: no vuelvas a pedir datos.' : '',
    e.anuncio && e.anuncio.titular ? 'Llego desde un anuncio: «' + e.anuncio.titular + '».' : '',
    finBloque ? 'Esta es la respuesta ' + topeAviso + ' de la conversacion: responde y, en este mismo mensaje, ofrece hablar con un asesor.' : '',
    '[MENSAJE DEL CLIENTE]',
    String(e.userInput ?? ''),
  ].filter(Boolean).join('\n');

  out.push({ json: {
    ...e,
    accion,
    etapa: c.etapa,
    respuestasEnVentana: siguiente,
    finBloque,
    primeraVez: nueva,
    leadConocido: lead,
    mensajeDelTurno,
  }, pairedItem: { item: i } });
}
return out;

// BIENVENIDA: la compuerta inicial de la especificacion. Dos BOTONES de
// respuesta y no una lista: dos opciones en una lista son dos toques, en
// botones uno, y cuestan lo mismo -- 1 mensaje --. Sin llamar al modelo.
//
// Los titulos de boton tienen un maximo de 20 caracteres (Meta). Si Meta
// rechazara el interactivo, `Enviar texto de respaldo` manda `textoRespaldo`.
return $input.all().map((it, i) => {
  const e = it.json;
  const cuerpo = '¡Hola! 👋 Soy el asistente virtual de ' + (e.nombreNegocio || 'NovuChat') +
    ', con inteligencia artificial. Para ayudarte mejor, cuéntame: ' +
    '¿ya eres cliente de NovuChat o quieres conocer el servicio?';
  return { json: { ...e,
    respuesta: cuerpo,
    cuerpoMeta: {
      messaging_product: 'whatsapp', recipient_type: 'individual', to: e.from,
      type: 'interactive',
      interactive: {
        type: 'button',
        body: { text: cuerpo },
        footer: { text: 'NovuChat · asistentes de WhatsApp para negocios' },
        action: { buttons: [
          { type: 'reply', reply: { id: 'cliente_actual', title: 'Soy cliente actual' } },
          { type: 'reply', reply: { id: 'cliente_nuevo', title: 'Soy cliente nuevo' } },
        ] },
      },
    },
    textoRespaldo: cuerpo + '\n\nEscríbeme «soy cliente» o cuéntame qué necesitas.',
  }, pairedItem: { item: i } };
});

// CLIENTE ACTUAL: un mensaje con la consola y un boton a una persona, y fin.
// Sin llamar al modelo.
//
// NO LLEVA NINGUN CODIGO. La especificacion pedia «Ingresa a la Consola con el
// codigo XXXXX»; la consola no tiene codigo -- se entra con correo y
// contrasena -- y un codigo fijo que se le da a cualquiera que toque «Soy
// cliente actual» seria una filtracion por diseño. Decidido por Andres el
// 14/09/2026 (CLIENTES/NOVUCHAT/01-… §8).
//
// El boton `cta_url` abre el WhatsApp de una persona. El texto del boton tiene
// un maximo de 20 caracteres. Si no hay numero de recepcion, va solo el texto.
return $input.all().map((it, i) => {
  const e = it.json;
  let cuerpo = String(e.mensajeClienteActual || '').trim();
  const enlace = String(e.enlaceConsola || '').trim();
  const dominio = enlace.replace(/^https?:\/\//, '').replace(/\/.*$/, '');
  if (enlace && dominio && !cuerpo.includes(dominio)) cuerpo += '\n\n' + enlace;

  const recepcion = String(e.numeroRecepcion || '').replace(/\D/g, '');
  const url = recepcion
    ? 'https://wa.me/' + recepcion + '?text=' +
      encodeURIComponent('Hola, soy cliente de NovuChat y necesito ayuda con la consola.')
    : '';

  return { json: { ...e,
    respuesta: cuerpo,
    cuerpoMeta: url ? {
      messaging_product: 'whatsapp', recipient_type: 'individual', to: e.from,
      type: 'interactive',
      interactive: {
        type: 'cta_url',
        body: { text: cuerpo },
        action: { name: 'cta_url', parameters: { display_text: 'Pedir ayuda', url } },
      },
    } : undefined,
    textoRespaldo: url ? cuerpo + '\n\nPara hablar con una persona: ' + url : cuerpo,
  }, pairedItem: { item: i } };
});

// USO EXTENDIDO: el servidor dice que este telefono paso el umbral de
// operador o el de bloqueo (`Analisis/27` §5, `atencion.ts`). Es el mismo
// mecanismo que obedecen los flujos A y B, con los umbrales de la cuenta del
// tenant (`cuenta/estado`: 50 y 100 por defecto). Cubre lo que la
// especificacion de Silvana llamaba «tope duro».
//
// NO SE LLAMA AL MODELO en ninguno de los dos casos: este nodo cuelga antes
// del agente.
//
//   operador  -> un mensaje fijo: una persona sigue la conversacion. Cuenta y
//                se factura como cualquier respuesta.
//   bloqueado -> no se responde nada al cliente.
//   En los dos, la PRIMERA vez que se entra al estado (el servidor lo marca en
//   `atencionAvisarRecepcion`) se avisa a una persona con la plantilla.
//
// El texto va con TUTEO, que es la voz de NovuChat. El del servidor
// (`MENSAJE_USO_EXTENDIDO`) es neutro y de usted, para los comercios.
const FIJO = 'Gracias por tu paciencia. Para atenderte mejor, una persona del equipo de ' +
  'NovuChat va a seguir esta conversación en breve, por este mismo WhatsApp.';

return $input.all().map((it, i) => {
  const e = it.json;
  const bloqueado = e.atencionEstado === 'bloqueado';
  const avisar = e.atencionAvisarRecepcion === 'operador' || e.atencionAvisarRecepcion === 'bloqueado';
  return { json: { ...e,
    responder: !bloqueado,
    respuesta: bloqueado ? '' : FIJO,
    avisar,
    estadoAviso: bloqueado ? 'llegó al límite de respuestas del día' : 'pasó a atención de una persona',
    estadoLead: bloqueado ? 'bloqueado' : 'operador',
    guardarLead: avisar,
  }, pairedItem: { item: i } };
});

// PROCESAR RESPUESTA: separa las marcas del agente y aplica por codigo la
// prohibicion 4 (el agente no niega ser una IA). Un modelo puede omitir una
// frase de las instrucciones; lo que no se negocia no depende de su voluntad.
//
// LAS MARCAS, que el cliente nunca ve:
//   [LEAD]{json}[/LEAD]  los datos del prospecto que el cliente dio o corrigio
//                        en este turno. Una sola llamada al modelo por turno:
//                        la extraccion viaja en la misma respuesta.
//   [CIERRE]             ya estan los datos obligatorios: se avisa a una
//                        persona y la respuesta sale con el boton a un asesor.
//
// UN [CIERRE] SIN LOS DATOS NO CIERRA. El modelo puede apurarse; el aviso
// interno cuesta un mensaje utility y le quita tiempo a una persona, asi que
// se exige que empresa, contacto, rubro y flujos esten de verdad registrados.
// La excepcion es el cliente actual que pide una persona: ahi no hay datos de
// prospecto que exigir.
const entradas = $('Estado de la conversación').all();
const sd = $getWorkflowStaticData('global');
sd.conversaciones = sd.conversaciones ?? {};

const NIEGA_IA = /(no\s+soy\s+(un[ao]?\s+)?(bot|robot|m[aá]quina|programa|inteligencia\s+artificial|\bia\b|asistente\s+virtual|autom[aá]tic[ao])|soy\s+(un[ao]?\s+)?(persona|humano|humana|ser\s+humano)|habl(as|[aá]s|a)\s+con\s+(un[ao]?\s+)?(persona|humano|humana))/i;
const CAMPOS = ['empresa', 'contacto', 'rubro', 'flujos', 'personalizacion', 'nit'];
const OBLIGATORIOS = ['empresa', 'contacto', 'rubro', 'flujos'];
// UN DATO DE RELLENO NO ES UN DATO. El 15/09 el modelo marco rubro «Pendiente»
// sin que el cliente dijera nada: contaba como registrado, y con los otros tres
// el cierre avisaba a un asesor por un prospecto a medias.
const RELLENO = /^(pendiente|por (definir|confirmar)|a definir|desconocid[oa]|no (especificad[oa]|indicad[oa]|informad[oa]|sabe|lo sabe|dijo)|sin (dato|datos|definir|especificar)|n\/?a|ninguno|null|undefined|-+|\?+|…|\.{3})$/i;

function leerLead(bruto) {
  const m = bruto.match(/\[LEAD\]([\s\S]*?)\[\/LEAD\]/i);
  if (!m) return { lead: {}, invalido: false };
  try {
    const j = JSON.parse(m[1].trim());
    const lead = {};
    for (const k of CAMPOS) {
      let v = j?.[k];
      if (Array.isArray(v)) v = v.map(String).join(', ');
      if (v === undefined || v === null) continue;
      v = String(v).replace(/\s+/g, ' ').trim().slice(0, 300);
      if (v && !RELLENO.test(v)) lead[k] = v;
    }
    return { lead, invalido: false };
  } catch {
    return { lead: {}, invalido: true };
  }
}

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  // Emparejamiento por indice: nunca .first(), que le pondria el telefono del
  // primer mensaje a todos los items si llegaran dos a la vez.
  const ent = (entradas[i] ?? entradas[entradas.length - 1]).json;
  const bruto = String(items[i].json.output ?? items[i].json.text ?? '').trim();

  const { lead, invalido } = leerLead(bruto);
  const pideCierre = /\[CIERRE\]/i.test(bruto);

  let texto = bruto
    .replace(/\[LEAD\][\s\S]*?\[\/LEAD\]/gi, '')
    .replace(/\[\/?LEAD\]/gi, '')
    .replace(/\[CIERRE\]/gi, '')
    .replace(/\[[A-ZÁÉÍÓÚÑ_ ]{3,30}\]/g, '')
    .trim();

  const avisos = [];
  if (invalido) avisos.push('lead_invalido');

  // --- Prohibicion 4: el agente no niega ser una IA ---------------------
  if (NIEGA_IA.test(texto)) {
    texto = texto.replace(NIEGA_IA, 'sí, soy un asistente virtual con inteligencia artificial');
    avisos.push('correccion_ia');
  }
  if (!texto) {
    texto = 'Disculpa, no pude generar la respuesta. ¿Me lo repites?';
    avisos.push('respuesta_vacia');
  }

  // --- Datos del prospecto: se acumulan en la conversacion ----------------
  const c = sd.conversaciones[ent.from];
  const previo = c?.lead ?? ent.leadConocido ?? {};
  const combinado = { ...previo, ...lead };
  const cambios = Object.keys(lead).filter((k) => previo[k] !== lead[k]);
  const completo = OBLIGATORIOS.every((k) => combinado[k]);
  const cierre = pideCierre && (completo || ent.etapa === 'cliente_actual');
  if (pideCierre && !cierre) avisos.push('cierre_sin_datos');
  const avisar = cierre && !(c?.avisado);

  if (c) {
    c.lead = combinado;
    if (avisar) c.avisado = true;
    if (cierre && c.etapa !== 'cliente_actual') c.etapa = 'cerrado';
  }

  // --- Boton a un asesor: en el cierre y al terminar el primer bloque ------
  const recepcion = String(ent.numeroRecepcion || '').replace(/\D/g, '');
  const conBoton = (cierre || ent.finBloque) && recepcion !== '';
  const nombre = combinado.contacto ? 'soy ' + combinado.contacto : 'soy un cliente';
  const url = conBoton
    ? 'https://wa.me/' + recepcion + '?text=' + encodeURIComponent(
      'Hola, ' + nombre + (combinado.empresa ? ' de ' + combinado.empresa : '') +
      ' y hablé con el asistente de NovuChat.')
    : '';

  out.push({ json: { ...ent,
    respuesta: texto,
    cuerpoMeta: url ? {
      messaging_product: 'whatsapp', recipient_type: 'individual', to: ent.from,
      type: 'interactive',
      interactive: {
        type: 'cta_url',
        body: { text: texto },
        action: { name: 'cta_url', parameters: { display_text: 'Hablar con un asesor', url } },
      },
    } : undefined,
    textoRespaldo: url ? texto + '\n\nPara hablar con un asesor: ' + url : texto,
    lead: combinado,
    guardarLead: cambios.length > 0 || ent.primeraVez === true || avisar,
    estadoLead: cierre ? 'cerrado' : 'en_conversacion',
    avisar,
    estadoAviso: ent.etapa === 'cliente_actual' ? 'pidió hablar con una persona' : 'datos completos',
    avisos,
  }, pairedItem: { item: i } });
}
return out;

// SALIDA: la ultima compuerta. TODO lo que sale al cliente pasa por aca, venga
// de la bienvenida, del cliente actual, del corte, del aviso de comercio no
// operativo o del agente. Arma tres cuerpos listos para enviar:
//
//   cuerpoMeta      el mensaje al cliente (interactivo o texto)
//   cuerpoRespaldo  el mismo en texto plano, por si Meta rechaza el interactivo
//   cuerpoAviso     la plantilla del aviso interno, si corresponde
//   cuerpoCrm       el registro del prospecto, si hay algo nuevo que guardar
//
// MENSAJES POR TURNO: UNO al cliente (o su respaldo si el primero fallo,
// nunca los dos), salvo con el telefono BLOQUEADO por el servidor, que no
// recibe nada (`responder: false`). El aviso interno es una plantilla utility
// aparte: +1 por prospecto cerrado y +1 por cada umbral que el servidor marca.
//
// Que el mensaje SALIO no lo decide este nodo: lo decide `Confirmar envio`, al
// final, con lo que contesto Meta. Solo eso se reporta y se da por hecho.
const LIMITE_INTERACTIVO = 1024;   // cuerpo de un mensaje interactivo (Meta)
const LIMITE_TEXTO = 4096;         // cuerpo de un mensaje de texto (Meta)

// Una variable de plantilla no admite saltos de linea, tabuladores ni mas de
// cuatro espacios seguidos, y no puede ir vacia: Meta rechaza el envio entero.
const variable = (v, max = 60) => {
  const t = String(v ?? '').replace(/[\r\n\t]+/g, ' · ').replace(/\s{2,}/g, ' ').trim();
  return (t || 'no indicado').slice(0, max);
};
const texto = (to, cuerpo) => ({
  messaging_product: 'whatsapp', recipient_type: 'individual', to,
  type: 'text', text: { preview_url: false, body: String(cuerpo).slice(0, LIMITE_TEXTO) },
});

return $input.all().map((it, i) => {
  const e = it.json;
  const responder = e.responder !== false;
  const respuesta = String(e.respuesta ?? '').trim()
    || 'Disculpa, no pude generar la respuesta. ¿Me lo repites?';
  const textoRespaldo = String(e.textoRespaldo ?? respuesta).trim() || respuesta;

  // Un interactivo con el cuerpo demasiado largo lo rechaza Meta: se manda
  // directo como texto, con el enlace adentro. Mejor eso que un envio fallido.
  let cuerpoMeta = e.cuerpoMeta && e.cuerpoMeta.type === 'interactive' ? e.cuerpoMeta : null;
  if (cuerpoMeta && String(cuerpoMeta.interactive?.body?.text ?? '').length > LIMITE_INTERACTIVO) {
    cuerpoMeta = null;
  }
  const esInteractivo = cuerpoMeta !== null;
  const cuerpoRespaldo = texto(e.from, textoRespaldo);
  // Sin interactivo: si la rama traia uno y hubo que bajarlo a texto, va el
  // respaldo -- que lleva el enlace adentro --; si nunca lo trajo, la respuesta.
  const enviado = esInteractivo ? respuesta : (e.cuerpoMeta ? textoRespaldo : respuesta);
  if (!cuerpoMeta) cuerpoMeta = texto(e.from, enviado);

  const lead = e.lead ?? e.leadConocido ?? {};
  const recepcion = String(e.numeroRecepcion || '').replace(/\D/g, '');
  // A NADIE SE LE AVISA DE SU PROPIO MENSAJE (misma regla que el Demo B, #68):
  // si quien escribe es el propio numero de recepcion -- una persona de NovuChat
  // probando desde su telefono --, el aviso seria un mensaje pagado que no le
  // dice nada nuevo. En produccion los numeros difieren y no cambia nada.
  const esElMismo = recepcion !== '' && recepcion === String(e.from ?? '').replace(/\D/g, '');
  const cuerpoAviso = e.avisar === true && recepcion && !esElMismo ? {
    messaging_product: 'whatsapp', recipient_type: 'individual', to: recepcion,
    type: 'template',
    template: {
      name: e.plantillaAviso || 'solicitud_contacto',
      language: { code: 'es' },
      components: [{ type: 'body', parameters: [
        e.estadoAviso, lead.empresa, lead.contacto || e.nombrePerfil,
        lead.rubro, lead.flujos, String(e.from ?? '').replace(/\D/g, ''),
      ].map((v) => ({ type: 'text', text: variable(v) })) }],
    },
  } : null;

  const crmUrl = String(e.crmUrl ?? '').trim();
  const guardar = /^https:\/\//.test(crmUrl) && (e.guardarLead === true || e.primeraVez === true);
  const cuerpoCrm = guardar ? {
    origen: 'whatsapp',
    telefono: String(e.from ?? ''),
    nombrePerfil: String(e.nombrePerfil ?? ''),
    estado: e.estadoLead || (e.accion === 'cliente_actual' ? 'cliente_actual' : 'en_conversacion'),
    ...lead,
    ...(e.anuncio ? { anuncio: e.anuncio } : {}),
    fecha: new Date().toISOString(),
  } : null;

  return { json: {
    from: e.from,
    phoneNumberId: e.phoneNumberId,
    waGraphVersion: e.waGraphVersion || 'v26.0',
    nombrePerfil: e.nombrePerfil,
    accion: e.accion ?? (e.comercioSuspendido ? 'comercio_no_operativo' : ''),
    responder,
    respuesta: responder ? String(enviado).slice(0, LIMITE_TEXTO) : '',
    // Lo que se reporta si sale el respaldo: `Confirmar envio` no abre cuerpos.
    respuestaRespaldo: responder ? String(textoRespaldo).slice(0, LIMITE_TEXTO) : '',
    esInteractivo,
    cuerpoMeta,
    cuerpoRespaldo,
    avisar: cuerpoAviso !== null,
    cuerpoAviso,
    guardar,
    crmUrl,
    cuerpoCrm,
    avisos: e.avisos ?? [],
  }, pairedItem: { item: i } };
});

// CONFIRMAR ENVIO: lo unico que se da por hecho es lo que Meta ACEPTO.
//
// CORRE AL FINAL. Es el hijo mas bajo de `Salida` en el lienzo y el flujo va
// con `executionOrder: v1`: cuando llega aca ya corrieron el envio al cliente
// (y su respaldo), el aviso interno y el CRM. Por eso puede leer el resultado
// del envio, y por eso un error aca no se lleva por delante al aviso ni al CRM.
// Si se lo sube en el lienzo, lee envios que todavia no ocurrieron.
//
// HACE TRES COSAS, sin ninguna llamada a Meta (lee lo que ya contesto):
//  1. Si Meta rechazo el mensaje -- el texto, o el interactivo Y su respaldo --
//     o el envio no llego a Meta, TERMINA LA EJECUCION EN ERROR con el codigo y
//     el mensaje de Meta. `Enviar a WhatsApp` usa `neverError` para poder
//     mandar el respaldo, y sin este nodo un texto rechazado terminaba en
//     «success» sin que nadie se enterara (aceptacion del 15/09/2026: Meta
//     respondio 190 por una credencial mal asignada). Asi lo encuentra
//     `scripts/ver-ejecuciones.sh --error`. El error NO lleva el texto de la
//     respuesta ni el telefono del cliente.
//  2. Solo lo que salio pasa a `Reportar mensaje (saliente)`. El servidor cuenta
//     cada saliente como una respuesta del bloque (`ingesta.ts`,
//     `mensajesVentana`): reportar uno que no salio se le facturaba al comercio.
//  3. Marca la bienvenida en los datos estaticos recien cuando Meta la acepto.
//     Marcada antes de enviar, un envio fallido dejaba a ese telefono sin los
//     botones para siempre.
const sd = $getWorkflowStaticData('global');
sd.conversaciones = sd.conversaciones ?? {};

const acepto = (r) => { const s = Number(r?.statusCode); return s >= 200 && s < 300; };

// Lo que devolvio un nodo de envio; nada si no corrio.
const salidaDe = (nombre) => {
  try {
    const n = $(nombre);
    if (n.isExecuted === false) return [];
    return n.all().map((x) => x.json);
  } catch (err) {
    return [];
  }
};

// Codigo y mensaje de Meta en una linea, sin datos del cliente.
const detalle = (r, telefono) => {
  if (!r) return 'el nodo de envío no devolvió nada';
  let cuerpo = r.body;
  if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (err) { cuerpo = {}; } }
  const e = cuerpo && typeof cuerpo === 'object' && cuerpo.error && typeof cuerpo.error === 'object'
    ? cuerpo.error
    : (r.error && typeof r.error === 'object' ? r.error : {});
  const partes = [r.statusCode != null ? 'HTTP ' + r.statusCode : 'sin respuesta HTTP'];
  if (e.code != null) partes.push('código ' + e.code);
  if (e.error_subcode != null) partes.push('subcódigo ' + e.error_subcode);
  if (e.type) partes.push(String(e.type));
  if (e.fbtrace_id) partes.push('fbtrace ' + e.fbtrace_id);
  let msg = String(e.message ?? e.description ?? (typeof r.error === 'string' ? r.error : ''));
  const digitos = String(telefono ?? '').replace(/\D/g, '');
  if (digitos.length >= 6) msg = msg.split(digitos).join('[destinatario]');
  msg = msg.replace(/\s+/g, ' ').trim().slice(0, 200);
  return partes.join(', ') + (msg ? ': ' + msg : '');
};

const items = $input.all().map((x) => x.json);
// El mismo criterio que `¿Responder?`: con el telefono bloqueado no se envio nada.
const aEnviar = items.filter((s) => s.responder !== false);
if (aEnviar.length === 0) return [];

const envios = salidaDe('Enviar a WhatsApp');
const respaldos = salidaDe('Enviar texto de respaldo');
const salen = [];
const fallas = [];
let r = 0;
aEnviar.forEach((s, k) => {
  const envio = envios[k];
  // El mismo criterio que `¿Falló el interactivo?`: solo entonces corrio el respaldo.
  const porRespaldo = Number(envio?.statusCode) >= 400 && s.esInteractivo === true;
  const final = porRespaldo ? respaldos[r++] : envio;
  const turno = 'turno ' + (s.accion || 'agente');
  if (!acepto(final)) {
    fallas.push(porRespaldo
      ? detalle(final, s.from) + ' (respaldo en texto, ' + turno + '; antes el interactivo: ' + detalle(envio, s.from) + ')'
      : detalle(final, s.from) + ' (' + (s.esInteractivo ? 'interactivo' : 'texto') + ', ' + turno + ')');
    return;
  }
  const c = sd.conversaciones[s.from];
  if (s.accion === 'bienvenida' && c) c.bienvenida = true;
  salen.push({ json: {
    from: s.from,
    phoneNumberId: s.phoneNumberId,
    esInteractivo: porRespaldo ? false : s.esInteractivo === true,
    respuesta: porRespaldo ? String(s.respuestaRespaldo ?? s.respuesta ?? '') : s.respuesta,
    porRespaldo,
  }, pairedItem: { item: items.indexOf(s) } });
});

if (fallas.length) throw new Error('Meta rechazó el mensaje al cliente: ' + fallas.join(' | '));
return salen;
